using Microsoft.Extensions.DependencyInjection;
using Allocation.Contracts;
using Allocation.Slices.Allocation;
using Shouldly;
using Wolverine;
using Xunit;

namespace Allocation.IntegrationTests.Slices.Allocation;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation. Pattern: automation. Status: ready.
/// LIVE, so every test here must pass.
///
/// BOTH EXECUTION MODES MUST SATISFY THESE UNCHANGED — that is what makes this folder a comparison rather
/// than two programs. The GWTs name the COMMAND, and neither mode changes what the command does; only what
/// sends it differs, which is ExecutionModeTests' subject.
///
/// The WHEN is not an HTTP post. This slice's command is issued by the trigger, in process, so the test
/// issues it the same way. The generated scaffold guessed "a 400 with ProblemDetails" for the rejection
/// because the generator cannot tell an automation's command from a typed one — a real limitation of the
/// kit, and the reason a rejection here is a <see cref="SliceOutcome"/> instead.
/// </summary>
public sealed class IssueGrantTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static string SlotStream(int n) => ReserveSlotState.StreamKey(SeedData.PoolId, n);
    private static string GrantStream(Guid grantId) => IssueGrantState.StreamKey(grantId.ToString());

    private static SlotReserved ReservedFor(Guid grantId, int slot = 1) =>
        new(SeedData.PoolId, slot, grantId, SeedData.SeededAt);

    /// <summary>WHEN the command alone, straight to the decider — a GWT's when= names a COMMAND.</summary>
    private async Task<SliceOutcome> Issue(Guid grantId, int slot = 1)
    {
        using var scope = Host.Services.CreateScope();
        var bus = scope.ServiceProvider.GetRequiredService<IMessageBus>();
        return await bus.InvokeAsync<SliceOutcome>(new IssueGrant(grantId, SeedData.PoolId, slot));
    }

    // A reserved slot is executed into a grant
    //   GIVEN Slot Reserved(grantId=$AcceptedGrant, slotNumber=1)
    //   WHEN  IssueGrant(grantId=$AcceptedGrant)
    //   THEN  Grant Issued(grantId=$AcceptedGrant, slotNumber=1)
    [Fact]
    public async Task AReservedSlotIsExecutedIntoAGrant()
    {
        await Given(SlotStream(1), ReservedFor(SeedData.AcceptedGrant));

        (await Issue(SeedData.AcceptedGrant)).Accepted.ShouldBeTrue();

        var issued = (await EventsFor(GrantStream(SeedData.AcceptedGrant)))
            .ShouldHaveSingleItem().ShouldBeOfType<GrantIssued>();
        issued.SlotNumber.ShouldBe(1);
        issued.GrantId.ShouldBe(SeedData.AcceptedGrant);
    }

    // A grant already issued is not issued twice
    //   GIVEN Slot Reserved(grantId=$AcceptedGrant), Grant Issued(grantId=$AcceptedGrant)
    //   WHEN  IssueGrant(grantId=$AcceptedGrant)
    //   THEN  error: AlreadyIssued
    [Fact]
    public async Task AGrantAlreadyIssuedIsNotIssuedTwice()
    {
        await Given(SlotStream(1), ReservedFor(SeedData.AcceptedGrant));
        await Given(GrantStream(SeedData.AcceptedGrant),
            new GrantIssued(SeedData.AcceptedGrant, SeedData.PoolId, 1, SeedData.SeededAt));

        var outcome = await Issue(SeedData.AcceptedGrant);

        outcome.Accepted.ShouldBeFalse();
        outcome.Error.ShouldBe(IssueGrantHandler.AlreadyIssued);

        // AND THE WORK DID NOT RUN AGAIN, which is what this rule is actually protecting. A second
        // GrantIssued would be the visible half; the invisible half is a second call to the executor,
        // which is the thing that cannot be undone.
        (await EventsFor(GrantStream(SeedData.AcceptedGrant))).Length.ShouldBe(1);
    }

    // Execution the work refuses is recorded as a fact rather than thrown away
    //   GIVEN Slot Reserved(grantId=$RefusedGrant, slotNumber=1)
    //   WHEN  IssueGrant(grantId=$RefusedGrant)
    //   THEN  Grant Refused(grantId=$RefusedGrant, slotNumber=1)
    [Fact]
    public async Task ExecutionTheWorkRefusesIsRecordedAsAFactRatherThanThrown()
    {
        await Given(SlotStream(1), ReservedFor(SeedData.RefusedGrant));

        // ACCEPTED, and that is the point of the scenario. The command was legal and the decider did its
        // job; the WORK said no. A rejection would lose the fact, and the compensating slice has nothing
        // to react to — which is why then= on this GWT names an event and not an error.
        (await Issue(SeedData.RefusedGrant)).Accepted.ShouldBeTrue();

        var refused = (await EventsFor(GrantStream(SeedData.RefusedGrant)))
            .ShouldHaveSingleItem().ShouldBeOfType<GrantRefused>();
        refused.SlotNumber.ShouldBe(1);
        refused.Reason.ShouldBe(StandInGrantExecutor.RefusalReason);
    }
}
